import React, { useState, useEffect, useRef, useCallback } from "react";
import { DOC_INDEX, NAV, fetchDoc, preloadAllDocs, SERVER_BASE } from "./useGithubDocs";
import SupportPortal from "./components/SupportPortal";
import SearchBar from "./components/SearchBar";

// ── Theme ─────────────────────────────────────────────────────────────────────
function useTheme() {
  const [dark, setDark] = useState(true);
  useEffect(() => {
    document.body.classList.toggle("light", !dark);
  }, [dark]);
  return [dark, () => setDark((d) => !d)];
}

// ── Markdown renderer ─────────────────────────────────────────────────────────
function esc(s) {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
function inline(t) {
  return t
    .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
    .replace(/\*(.+?)\*/g, "<em>$1</em>")
    .replace(/`(.+?)`/g, "<code>$1</code>")
    .replace(
      /\[(.+?)\]\(#(.+?)\)/g,
      '<a href="#" data-doc="$2" class="doc-lnk">$1 →</a>',
    )
    .replace(/\[(.+?)\]\(mailto:(.+?)\)/g, '<a href="mailto:$2">$1</a>')
    .replace(
      /\[(.+?)\]\((.+?)\)/g,
      '<a href="$2" target="_blank" rel="noopener">$1</a>',
    );
}
function renderMD(text) {
  if (!text) return "";
  const lines = text.split("\n");
  let html = "",
    inCode = false,
    inTable = false,
    inList = false,
    lt = "",
    inBq = false;
  const closeL = () => {
    if (inList) {
      html += `</${lt}>`;
      inList = false;
    }
  };
  const closeBq = () => {
    if (inBq) {
      html += "</blockquote>";
      inBq = false;
    }
  };
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.trim().startsWith("```")) {
      if (inCode) {
        html += "</code></pre>";
        inCode = false;
      } else {
        closeL();
        closeBq();
        html += "<pre><code>";
        inCode = true;
      }
      continue;
    }
    if (inCode) {
      html += esc(line) + "\n";
      continue;
    }
    if (inList && !/^\s*[-*]\s|^\d+\.\s/.test(line) && line.trim()) closeL();
    if (inBq && !line.startsWith(">")) closeBq();
    if (line.includes("|") && line.trim().startsWith("|")) {
      const cells = line
        .trim()
        .split("|")
        .filter((_, i2, a) => i2 > 0 && i2 < a.length - 1);
      const isSep = cells.every(
        (c) => c.trim().replace(/[-:]/g, "").trim() === "",
      );
      if (isSep) {
        if (!inTable) {
          html += "<table>";
          inTable = true;
        }
        continue;
      }
      if (!inTable) {
        html += "<table>";
        inTable = true;
      }
      const isH = lines[i + 1]?.includes("---");
      html += `<tr>${cells.map((c) => `<${isH ? "th" : "td"}>${inline(c.trim())}</${isH ? "th" : "td"}>`).join("")}</tr>`;
      continue;
    } else if (inTable) {
      html += "</table>";
      inTable = false;
    }
    const hm = line.match(/^(#{1,6})\s(.+)/);
    if (hm) {
      closeL();
      closeBq();
      const lvl = hm[1].length;
      const id = hm[2]
        .toLowerCase()
        .replace(/[^a-z0-9\s]/g, "")
        .trim()
        .replace(/\s+/g, "-");
      html += `<h${lvl} id="${id}">${inline(hm[2])}</h${lvl}>`;
      continue;
    }
    if (/^---+$/.test(line.trim())) {
      closeL();
      closeBq();
      html += "<hr/>";
      continue;
    }
    if (line.startsWith("> ")) {
      if (!inBq) {
        html += "<blockquote>";
        inBq = true;
      }
      html += `<p>${inline(line.slice(2))}</p>`;
      continue;
    }
    if (/^\s*[-*]\s/.test(line)) {
      if (!inList || lt !== "ul") {
        closeL();
        html += "<ul>";
        inList = true;
        lt = "ul";
      }
      html += `<li>${inline(line.trim().slice(2))}</li>`;
      continue;
    }
    if (/^\s*\d+\.\s/.test(line)) {
      if (!inList || lt !== "ol") {
        closeL();
        html += "<ol>";
        inList = true;
        lt = "ol";
      }
      html += `<li>${inline(line.replace(/^\s*\d+\.\s/, "").trim())}</li>`;
      continue;
    }
    if (line.trim() === "") {
      closeL();
      closeBq();
      html += '<div class="sp"></div>';
      continue;
    }
    html += `<p>${inline(line)}</p>`;
  }
  if (inCode) html += "</code></pre>";
  if (inTable) html += "</table>";
  if (inList) html += `</${lt}>`;
  if (inBq) html += "</blockquote>";
  return html;
}
function extractTOC(c) {
  return (c || "")
    .split("\n")
    .filter((l) => /^#{2,4}\s/.test(l))
    .map((l) => {
      const m = l.match(/^(#{2,4})\s(.+)/);
      return {
        level: m[1].length,
        text: m[2],
        id: m[2]
          .toLowerCase()
          .replace(/[^a-z0-9\s]/g, "")
          .trim()
          .replace(/\s+/g, "-"),
      };
    });
}

