const HeroSection = ({ onDocsClick, onSupportClick }) => {
  const canvasRef = useRef(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    canvas.width = canvas.offsetWidth;
    canvas.height = canvas.offsetHeight;
    const W = canvas.width,
      H = canvas.height;
    const cx = W / 2,
      cy = H / 2,
      R = Math.min(W, H) * 0.35;
    let frame = 0;
    const animate = () => {
      ctx.clearRect(0, 0, W, H);
      const t = frame * 0.008;
      // globe rings
      for (let i = 0; i < 5; i++) {
        const a = (i / 5) * Math.PI;
        ctx.beginPath();
        ctx.ellipse(
          cx,
          cy,
          R,
          R * Math.abs(Math.cos(a + t)),
          0,
          0,
          Math.PI * 2,
        );
        ctx.strokeStyle = `rgba(0,180,255,${0.08 + i * 0.03})`;
        ctx.lineWidth = 1;
        ctx.stroke();
      }
      // outer circle
      ctx.beginPath();
      ctx.arc(cx, cy, R, 0, Math.PI * 2);
      ctx.strokeStyle = "rgba(0,180,255,0.25)";
      ctx.lineWidth = 1.5;
      ctx.stroke();
      // inner dot
      ctx.beginPath();
      ctx.arc(cx, cy, 4, 0, Math.PI * 2);
      ctx.fillStyle = "var(--accent)";
      ctx.fill();
      // radar sweep
      const angle = t * 2;
      const grad = ctx.createConicalGradient ? null : null;
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.arc(cx, cy, R, angle, angle + 0.8);
      ctx.closePath();
      ctx.fillStyle = "rgba(0,180,255,0.06)";
      ctx.fill();
      // dots on globe
      for (let i = 0; i < 8; i++) {
        const da = (i / 8) * Math.PI * 2 + t;
        const x = cx + Math.cos(da) * R * 0.7;
        const y = cy + Math.sin(da) * R * 0.5;
        ctx.beginPath();
        ctx.arc(x, y, 2, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(0,212,160,${0.4 + Math.sin(da * 3 + t) * 0.3})`;
        ctx.fill();
      }
      frame++;
      requestAnimationFrame(animate);
    };
    animate();
  }, []);

  return (
    <section
      id="home"
      style={{
        minHeight: "100vh",
        display: "flex",
        alignItems: "center",
        position: "relative",
        overflow: "hidden",
