              fontSize: 10,
              fontWeight: 700,
              color: "var(--text-dim)",
              letterSpacing: "0.12em",
              textTransform: "uppercase",
              fontFamily: "var(--font-mono)",
            }}
          >
            {section}
          </div>
          {Object.entries(cats)
            .filter(([, items]) => items.length > 0)
            .map(([cat, items]) => {
              const key = `${section}::${cat}`;
              const open = isOpen(key);
